# CLAUDE.md

This file provides guidance to Claude Code (claude.ai/code) when working with code in this repository.

## Project Overview

mise-versions is a service that tracks and stores version numbers for tools supported by [mise](https://mise.jdx.dev/). It consists of:

1. **Version collection**: Shell scripts run via GitHub Actions (every 15 min) that fetch versions using `mise ls-remote` in Docker
2. **Version data files**: Plain text version files and TOML files (with timestamps) committed under `docs/`
3. **Web app**: Astro-based frontend deployed to Cloudflare Workers at `mise-tools.jdx.dev`
4. **Analytics API**: Download tracking and statistics via Cloudflare D1 database

## Common Commands

```bash
# Install dependencies
aube install

# Run tests
aube run test              # Run all tests (JS + shell)
aube run test:js           # JS unit tests only
aube run test:shell        # Shell script tests only

# Run a single JS test file
node --test scripts/generate-toml.test.js

# Web development (from web/ directory)
aube --dir web run dev     # Start Astro dev server
aube --dir web run build   # Build for production

# TypeScript checking
aube exec tsc              # Check types (root)
aube --dir web exec tsc    # Check types (web)

# Linting (or use `mise run lint` / `mise run lint:fix`)
aube exec eslint . --ext .ts
aube exec prettier --check .

# Local development
mise run dev               # or: aube exec wrangler dev

# Deploy
mise run deploy            # builds then deploys
```

## Architecture

### Data Flow

1. **Version Collection** (`scripts/update.sh`):
   - Runs `mise ls-remote <tool>` in Docker for each tool
   - Writes plain text to `docs/<tool>` and TOML with timestamps to `docs/<tool>.toml`
   - Syncs tool metadata to D1 via `scripts/sync-to-d1.js` (reads TOML files + mise commands)
   - Syncs version data to D1 via `scripts/sync-versions-to-d1.js`

2. **Metadata Collection** (`scripts/fetch-metadata.js`, weekly):
   - Fetches license, homepage, authors from GitHub/npm/crates.io/PyPI/RubyGems
   - Syncs directly to D1 via `/api/admin/metadata/sync`

3. **Storage**:
   - **Git repository** (`docs/`): Plain text and TOML version files used as the source for sync jobs and raw GitHub-backed data endpoints
   - **Cloudflare R2** (`DATA_BUCKET`): Binary .gz files only (python-precompiled)
   - **Cloudflare D1** (`ANALYTICS_DB`): Tool metadata, version data, and download analytics

4. **Web Frontend** (`web/`):
   - Astro + Preact + Tailwind
   - Pages: index (tool search), tool detail pages, stats, admin
   - API routes under `web/src/pages/api/`

### Key Files

- `src/analytics/`: Drizzle ORM schema and analytics functions for D1 (schema, tracking, stats, trends, rollups)
- `src/worker.ts`: Custom worker wrapper for scheduled tasks (daily rollups, maintenance)
- `web/src/lib/data-loader.ts`: Centralized data loading from D1
- `scripts/update.sh`: Main version fetching logic with token management
- `scripts/sync-to-d1.js`: Syncs tool metadata from TOML files to D1
- `scripts/sync-versions-to-d1.js`: Syncs version data to D1
- `scripts/fetch-metadata.js`: Fetches external metadata (license, homepage) and syncs to D1
- `scripts/generate-toml.js`: TOML file generation with timestamp preservation
- `wrangler.jsonc`: Cloudflare Workers configuration (D1, R2, KV bindings)

### D1 Database Schema

The `ANALYTICS_DB` contains:

- `tools`: Tool metadata (name, latest_version, description, backends, etc.)
- `versions`: Per-tool version data with created_at timestamps
- `downloads`: Raw download tracking
- `downloads_daily`: Aggregated historical data (90+ days old)
- Rollup tables: `daily_stats`, `daily_tool_stats`, `daily_backend_stats`
- `version_requests`: DAU/MAU tracking for mise CLI

## GitHub Token Management

The update workflow uses a token rotation system:

- `TOKEN_MANAGER_URL` / `TOKEN_MANAGER_SECRET`: Cloudflare Worker API for token pool
- `scripts/github-token.js`: Gets tokens, marks rate-limited tokens
- Tokens rotate automatically when rate limited
import { useState, useRef, useEffect } from "preact/hooks";

const MAX_SUGGESTIONS = 8;

interface Suggestion {
  name: string;
  description?: string;
}

export function NavSearch({ initialQuery = "" }: { initialQuery?: string }) {
  const [query, setQuery] = useState(initialQuery);
  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const debounceRef = useRef<number>();
  const inputRef = useRef<HTMLInputElement>(null);

  const fetchSuggestions = async (q: string) => {
    if (!q.trim()) {
      setSuggestions([]);
      return;
    }
    try {
      const res = await fetch(
        `/api/tools?q=${encodeURIComponent(q.trim())}&limit=${MAX_SUGGESTIONS}`,
      );
      // Drop responses whose query no longer matches the input (out-of-order
      // resolves or a superseded keystroke) so the dropdown never goes stale.
      if (inputRef.current && inputRef.current.value.trim() !== q.trim())
        return;
      if (!res.ok) {
        setSuggestions([]);
        return;
      }
      const data = await res.json();
      setSuggestions((data.tools || []).slice(0, MAX_SUGGESTIONS));
    } catch (e) {
      console.error("Failed to fetch search suggestions:", e);
      setSuggestions([]);
    }
  };

  const handleInput = (value: string) => {
    setQuery(value);
    setShowSuggestions(true);
    clearTimeout(debounceRef.current);
    debounceRef.current = window.setTimeout(() => fetchSuggestions(value), 300);
  };

  // Reset the highlight when the list changes. -1 means "nothing selected", so
  // Enter runs a full search (/?q=) instead of jumping to the first tool.
  useEffect(() => {
    setSelectedIndex(-1);
  }, [suggestions]);

  // Cancel a pending debounce if we unmount before it fires.
  useEffect(() => () => clearTimeout(debounceRef.current), []);

  const goToTool = (name: string) => {
    window.location.href = `/tools/${name}`;
  };

  const goToResults = () => {
    const q = query.trim();
    // Empty query resets to the full, unfiltered list.
    window.location.href = q ? `/?q=${encodeURIComponent(q)}` : "/";
  };

  const handleKeyDown = (e: KeyboardEvent) => {
    if (e.key === "Escape") {
      e.preventDefault();
      setShowSuggestions(false);
      inputRef.current?.blur();
      return;
    }
    if (e.key === "Enter") {
      e.preventDefault();
      if (
        showSuggestions &&
        selectedIndex >= 0 &&
        selectedIndex < suggestions.length
      ) {
        goToTool(suggestions[selectedIndex].name);
      } else {
        goToResults();
      }
      return;
    }
    if (!showSuggestions || suggestions.length === 0) return;
    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        // Cycle forward, passing through -1 (no selection) after the last item.
        setSelectedIndex((prev) =>
          prev < suggestions.length - 1 ? prev + 1 : -1,
        );
        break;
      case "ArrowUp":
        e.preventDefault();
        setSelectedIndex((prev) =>
          prev > -1 ? prev - 1 : suggestions.length - 1,
        );
        break;
    }
  };

  return (
    <div class="relative min-w-0 flex-1 sm:w-56 sm:flex-none md:w-64">
      <input
        ref={inputRef}
        type="text"
        placeholder="Search tools..."
        value={query}
        onInput={(e) => handleInput((e.target as HTMLInputElement).value)}
        onFocus={() => setShowSuggestions(true)}
        onBlur={() => setTimeout(() => setShowSuggestions(false), 150)}
        onKeyDown={handleKeyDown}
        class="w-full px-3 py-1.5 bg-dark-900 border border-dark-600 rounded-lg text-sm text-gray-100 placeholder-gray-500 focus:outline-none focus:border-neon-purple focus:ring-1 focus:ring-neon-purple"
        autocomplete="off"
      />
      {showSuggestions && suggestions.length > 0 && (
        <div class="absolute z-50 w-full mt-1 bg-dark-800 border border-dark-600 rounded-lg shadow-lg overflow-hidden">
          {suggestions.map((tool, index) => (
            <button
              key={tool.name}
              type="button"
              onMouseDown={() => goToTool(tool.name)}
              class={`w-full px-3 py-2 text-left text-sm transition-colors ${
                index === selectedIndex
                  ? "bg-neon-purple/20 text-neon-purple"
                  : "text-gray-300 hover:bg-dark-700"
              }`}
            >
              {tool.name}
              {tool.description && (
                <span class="ml-2 text-xs text-gray-500">
                  {tool.description.slice(0, 40)}
                  {tool.description.length > 40 ? "..." : ""}
                </span>
              )}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
  };

  // Clear all filters
  const handleClearFilters = () => {
    setSelectedBackends(new Set());
    fetchTools({
      page: 1,
      search,
      sort: sortBy,
      backends: [],
    });
