import Layout from '../layouts/Layout.astro';
import MauHistory from '../components/MauHistory.astro';
import { drizzle } from 'drizzle-orm/d1';
import { setupAnalytics } from '../../../src/analytics';
import { loadToolsJson, type ToolsData } from '../lib/data-loader';
import { formatCompact } from '../lib/format';
import type { GrowthData } from '../hooks/useGrowth';

import { env } from "cloudflare:workers";
// Version updates data type (now from D1)
interface VersionUpdatesData {
  daily: Array<{ date: string; count: number }>;
  total_updates: number;
  unique_tools: number;
  avg_per_day: number;
  days: number;
}

// Get the D1 database from Cloudflare runtime
const db = drizzle(env.ANALYTICS_DB);
const analytics = setupAnalytics(db, {
  analyticsEngine: {
    accountId: env.ANALYTICS_ENGINE_ACCOUNT_ID,
    apiToken: env.ANALYTICS_ENGINE_API_TOKEN,
    dataset: env.ANALYTICS_ENGINE_DATASET,
    cutoverDate: env.ANALYTICS_ENGINE_CUTOVER_DATE,
  },
});

// Load tools from D1 database
let toolsData: ToolsData = { tool_count: 0, tools: [] };
try {
  const data = await loadToolsJson(env.ANALYTICS_DB);
  if (data) {
    toolsData = data;
  }
} catch (e) {
  console.error('Failed to load tools from D1:', e);
}

// Fetch analytics data with error handling for local dev
let downloads: Record<string, number> = {};
let backendStatsData: { downloads_by_backend: Array<{ backend: string; count: number }>; top_tools_by_backend: Record<string, Array<{ tool: string; count: number }>> } | null = null;
let dauMauData: { daily: Array<{ date: string; dau: number; mau: number }>; current_mau: number } | null = null;
let growthData: GrowthData | null = null;
let versionUpdatesData: VersionUpdatesData | null = null;

try {
  [downloads, backendStatsData, dauMauData, growthData, versionUpdatesData] = await Promise.all([
    analytics.getAll30DayDownloads(),
    analytics.getBackendStats(),
    analytics.getDAUMAUHistory(370),
    analytics.getGrowthMetrics(),
    analytics.getVersionUpdates(30),
  ]);
} catch (e) {
  console.error('Failed to fetch analytics data:', e);
  // Use empty/mock data for local dev
}

// Helper functions
function getBackendType(backend: string): string {
  const colonIndex = backend.indexOf(":");
  return colonIndex > 0 ? backend.slice(0, colonIndex) : backend;
}

const BACKEND_COLORS: Record<string, string> = {
  aqua: "var(--data)",
  ubi: "var(--accent)",
  asdf: "#FF2D95",
  vfox: "#22C55E",
  cargo: "#F97316",
  npm: "#EF4444",
  go: "#3B82F6",
  pipx: "#8B5CF6",
  core: "var(--forecast)",
  gem: "#EC4899",
};

function getBackendColor(backend: string): string {
  return BACKEND_COLORS[backend] || "var(--muted)";
}

// Compute backend statistics (derived from tools.json for tool counts)
const backendCounts = new Map<string, number>();
const downloadsByBackendDerived = new Map<string, number>();

for (const tool of toolsData.tools) {
  const toolDownloads = downloads?.[tool.name] || 0;
  if (tool.backends && tool.backends.length > 0) {
    const primaryBackend = tool.backends[0];
    const backendType = getBackendType(primaryBackend);
    backendCounts.set(backendType, (backendCounts.get(backendType) || 0) + 1);
    downloadsByBackendDerived.set(
      backendType,
      (downloadsByBackendDerived.get(backendType) || 0) + toolDownloads
    );
  }
}
