import { setupAnalytics } from '../../../src/analytics';
import { loadToolsJson, type ToolsData } from '../lib/data-loader';
import { formatCompact } from '../lib/format';
import type { GrowthData } from '../hooks/useGrowth';

import { env } from "cloudflare:workers";
// Version updates data type (now from D1)
interface VersionUpdatesData {
  daily: Array<{ date: string; count: number }>;
  total_updates: number;
  unique_tools: number;
  avg_per_day: number;
  days: number;
}

// Get the D1 database from Cloudflare runtime
const db = drizzle(env.ANALYTICS_DB);
const analytics = setupAnalytics(db, {
  analyticsEngine: {
    accountId: env.ANALYTICS_ENGINE_ACCOUNT_ID,
    apiToken: env.ANALYTICS_ENGINE_API_TOKEN,
    dataset: env.ANALYTICS_ENGINE_DATASET,
    cutoverDate: env.ANALYTICS_ENGINE_CUTOVER_DATE,
  },
});

