import { useState, useEffect } from "preact/hooks";

// Version colors for stacked chart
const VERSION_COLORS = [
  "var(--accent)", // Purple
  "var(--data)", // Cyan
  "#FF2D95", // Pink
  "#22C55E", // Green
  "#F97316", // Orange
  "#3B82F6", // Blue
  "#8B5CF6", // Violet
  "var(--forecast)", // Yellow
  "#EF4444", // Red
  "var(--muted)", // Gray
];

function formatAxisNumber(n: number): string {
  if (n >= 1000000) return `${(n / 1000000).toFixed(1)}M`;
  if (n >= 1000) return `${(n / 1000).toFixed(n >= 10000 ? 0 : 1)}k`;
  return n.toString();
}

function moveDailyBarFocus(event: KeyboardEvent) {
  const current = event.currentTarget as HTMLElement;
  const bars = [
    ...(current.parentElement?.querySelectorAll<HTMLElement>(
      "[data-daily-bar]",
    ) || []),
  ];
  const currentIndex = bars.indexOf(current);
  let nextIndex = currentIndex;

  if (event.key === "ArrowLeft") nextIndex = Math.max(0, currentIndex - 1);
  else if (event.key === "ArrowRight") {
    nextIndex = Math.min(bars.length - 1, currentIndex + 1);
  } else if (event.key === "Home") nextIndex = 0;
  else if (event.key === "End") nextIndex = bars.length - 1;
  else return;

  event.preventDefault();
  for (const bar of bars) bar.tabIndex = -1;
  bars[nextIndex].tabIndex = 0;
  bars[nextIndex].focus();
}

function DailyBarChart({
  daily,
}: {
  daily: Array<{ date: string; count: number }>;
}) {
  if (!daily || daily.length === 0) {
    return <div class="text-gray-500 text-sm py-4">No download data yet</div>;
  }

  const maxCount = Math.max(...daily.map((d) => d.count), 1);

  // Fill in missing days for the last 30 days (excluding today since it's incomplete)
  const today = new Date();
  const days: Array<{ date: string; count: number }> = [];
  const dailyMap = new Map(daily.map((d) => [d.date, d.count]));

  for (let i = 30; i >= 1; i--) {
    const date = new Date(today);
    date.setDate(date.getDate() - i);
    const dateStr = date.toISOString().split("T")[0];
    days.push({ date: dateStr, count: dailyMap.get(dateStr) || 0 });
  }

  return (
    <div class="flex">
      {/* Y-axis labels */}
      <div class="flex flex-col justify-between text-xs text-gray-500 pr-2 h-32">
        <span>{formatAxisNumber(maxCount)}</span>
        <span>{formatAxisNumber(Math.round(maxCount / 2))}</span>
        <span>0</span>
      </div>
      {/* Chart */}
      <div
        class="flex-1 h-32 flex items-end gap-0.5"
        role="group"
        aria-label="Daily downloads by date. Use the left and right arrow keys to inspect days."
      >
        {days.map((d, index) => {
          const height = maxCount > 0 ? (d.count / maxCount) * 100 : 0;
          const dateObj = new Date(d.date);
          const label = dateObj.toLocaleDateString("en-US", {
            month: "short",
            day: "numeric",
          });
          return (
            <div
              key={d.date}
              class="flex-1 h-full flex items-end group relative outline-none"
              aria-label={`${label}: ${d.count.toLocaleString()} downloads`}
              data-daily-bar
              tabIndex={index === days.length - 1 ? 0 : -1}
              onKeyDown={moveDailyBarFocus}
            >
              <div
                class="w-full bg-neon-purple hover:bg-neon-pink transition-colors rounded-t"
                style={{ height: `${Math.max(height, 2)}%` }}
              />
              <div class="absolute bottom-full left-1/2 -translate-x-1/2 mb-1 px-2 py-1 bg-dark-700 rounded text-xs text-gray-300 opacity-0 group-hover:opacity-100 group-focus:opacity-100 transition-opacity whitespace-nowrap pointer-events-none z-10">
                {label}: {d.count.toLocaleString()} downloads
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

